import { useMemo, useState } from "react";
import { Link } from "react-router-dom";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Progress } from "@/components/ui/progress";
import { Cloud, Shield, ChevronRight, Scan, Download } from "lucide-react";
import { scanIaC, postureScore, SAMPLE_IAC, type CspmFinding } from "@/lib/cloud-cspm/engine";

const SEV: Record<string, string> = {
  critical: "bg-red-500/15 text-red-400 border-red-500/30",
  high: "bg-orange-500/15 text-orange-400 border-orange-500/30",
  medium: "bg-amber-500/15 text-amber-400 border-amber-500/30",
  low: "bg-blue-500/15 text-blue-400 border-blue-500/30",
};

export default function CloudCSPM() {
  const [input, setInput] = useState("");
  const [findings, setFindings] = useState<CspmFinding[]>([]);
  const [scanned, setScanned] = useState(false);

  const score = useMemo(() => postureScore(findings), [findings]);

  const runScan = () => {
    const text = input.trim() || SAMPLE_IAC;
    if (!input.trim()) setInput(SAMPLE_IAC);
    setFindings(scanIaC(text));
    setScanned(true);
  };

  const exportReport = () => {
    const md = `# CSPM Posture Report\nScore: ${score}/100\nFindings: ${findings.length}\n\n${findings.map((f) =>
      `## ${f.title} (${f.severity})\n- Provider: ${f.provider}\n- Resource: ${f.resource}\n- Fix: ${f.recommendation}\n- Compliance: ${f.compliance.join(", ")}`,
    ).join("\n\n")}`;
    const blob = new Blob([md], { type: "text/markdown" });
    const a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = `cspm-report-${new Date().toISOString().slice(0, 10)}.md`;
    a.click();
  };

  return (
    <div className="container mx-auto px-4 py-8 max-w-6xl">
      <div className="mb-6 flex items-center gap-2 text-xs text-muted-foreground">
        <Link to="/hub" className="hover:text-cyan-400">Platform Hub</Link>
        <ChevronRight className="h-3 w-3" />
        <Link to="/company/cloud-security" className="hover:text-cyan-400">Cloud Security</Link>
        <ChevronRight className="h-3 w-3" />
        <span className="text-sky-400">CSPM Scanner</span>
      </div>

      <div className="flex items-start gap-4 mb-8">
        <div className="flex h-12 w-12 items-center justify-center rounded-xl bg-gradient-to-br from-sky-400 to-blue-600">
          <Cloud className="h-6 w-6 text-white" />
        </div>
        <div>
          <h1 className="text-2xl font-bold">Multi-Cloud CSPM Scanner</h1>
          <p className="text-sm text-muted-foreground mt-1">
            Scan Terraform, Kubernetes YAML, and IaC for AWS · Azure · GCP misconfigurations
          </p>
        </div>
      </div>

      <div className="grid gap-6 lg:grid-cols-3">
        <div className="lg:col-span-2 space-y-4">
          <Card>
            <CardHeader className="pb-2">
              <CardTitle className="text-sm">Paste IaC / Terraform / K8s manifest</CardTitle>
            </CardHeader>
            <CardContent className="space-y-3">
              <Textarea
                value={input}
                onChange={(e) => setInput(e.target.value)}
                placeholder="Paste Terraform, CloudFormation, or Kubernetes YAML…"
                rows={14}
                className="font-mono text-xs"
              />
              <div className="flex gap-2">
                <Button onClick={runScan}>
                  <Scan className="h-4 w-4 mr-1.5" /> Run posture scan
                </Button>
                <Button variant="outline" onClick={() => { setInput(SAMPLE_IAC); }}>
                  Load sample
                </Button>
              </div>
            </CardContent>
          </Card>

          {scanned && (
            <Card>
              <CardHeader className="pb-2 flex flex-row items-center justify-between">
                <CardTitle className="text-sm">Findings ({findings.length})</CardTitle>
                <Button variant="ghost" size="sm" onClick={exportReport}>
                  <Download className="h-4 w-4 mr-1" /> Export
                </Button>
              </CardHeader>
              <CardContent className="space-y-3 max-h-[420px] overflow-y-auto">
                {findings.length === 0 ? (
                  <p className="text-sm text-emerald-400 flex items-center gap-2">
                    <Shield className="h-4 w-4" /> No misconfigurations detected
                  </p>
                ) : findings.map((f) => (
                  <div key={f.id} className="rounded-lg border border-white/5 p-3 bg-white/[0.02]">
                    <div className="flex justify-between gap-2">
                      <p className="text-sm font-medium">{f.title}</p>
                      <Badge variant="outline" className={SEV[f.severity]}>{f.severity}</Badge>
                    </div>
                    <p className="text-xs text-muted-foreground mt-1">
                      {f.provider.toUpperCase()} · {f.resource}{f.line ? ` · line ${f.line}` : ""}
                    </p>
                    <p className="text-xs text-cyan-400/80 mt-2">{f.recommendation}</p>
                    <div className="flex flex-wrap gap-1 mt-2">
                      {f.compliance.map((c) => (
                        <Badge key={c} variant="secondary" className="text-[10px]">{c}</Badge>
                      ))}
                    </div>
                  </div>
                ))}
              </CardContent>
            </Card>
          )}
        </div>

        <div className="space-y-4">
          <Card className="border-sky-500/20">
            <CardContent className="pt-6 text-center">
              <p className="text-xs uppercase tracking-widest text-muted-foreground">Posture score</p>
              <p className={`text-5xl font-bold mt-2 ${score >= 70 ? "text-emerald-400" : score >= 40 ? "text-amber-400" : "text-red-400"}`}>
                {scanned ? score : "—"}
              </p>
              {scanned && <Progress value={score} className="mt-4 h-2" />}
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="pb-2"><CardTitle className="text-sm">Coverage</CardTitle></CardHeader>
            <CardContent className="text-xs text-muted-foreground space-y-2">
              {["AWS (S3, SG, RDS, IAM, CloudTrail)", "Azure Storage", "GCP GCS", "Kubernetes pods", "Terraform secrets"].map((x) => (
                <p key={x} className="flex items-center gap-2"><span className="h-1 w-1 rounded-full bg-sky-400" />{x}</p>
              ))}
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  );
}
