export type CspmSeverity = "critical" | "high" | "medium" | "low";

export type CspmFinding = {
  id: string;
  ruleId: string;
  title: string;
  severity: CspmSeverity;
  provider: "aws" | "azure" | "gcp" | "k8s" | "generic";
  resource: string;
  line?: number;
  recommendation: string;
  compliance: string[];
};

type Rule = {
  id: string;
  title: string;
  severity: CspmSeverity;
  provider: CspmFinding["provider"];
  pattern: RegExp;
  resource: string;
  recommendation: string;
  compliance: string[];
};

