function uid() {
  return crypto.randomUUID?.() ?? `cspm-${Date.now()}`;
}

function lineAt(content: string, index: number): number {
  return content.slice(0, index).split("\n").length;
}

export function scanIaC(content: string, filename = "input.tf"): CspmFinding[] {
  const findings: CspmFinding[] = [];
  const seen = new Set<string>();

  for (const rule of RULES) {
    rule.pattern.lastIndex = 0;
    let m: RegExpExecArray | null;
    while ((m = rule.pattern.exec(content)) !== null) {
      const line = lineAt(content, m.index);
      const key = `${rule.id}:${line}`;
      if (seen.has(key)) continue;
      seen.add(key);
      findings.push({
        id: uid(),
        ruleId: rule.id,
        title: rule.title,
        severity: rule.severity,
        provider: rule.provider,
        resource: rule.resource,
        line,
        recommendation: rule.recommendation,
        compliance: rule.compliance,
      });
    }
  }

  const order: CspmSeverity[] = ["critical", "high", "medium", "low"];
  return findings.sort((a, b) => order.indexOf(a.severity) - order.indexOf(b.severity));
}

export function postureScore(findings: CspmFinding[]): number {
  const weights = { critical: 20, high: 12, medium: 6, low: 2 };
  const penalty = findings.reduce((s, f) => s + (weights[f.severity] ?? 0), 0);
  return Math.max(0, 100 - Math.min(100, penalty));
}

